// Dispatcher settings.json timeout derivation — mt#3981 (absorbing mt#3675).
//
// Each `.claude/settings.json` dispatcher entry's `timeout` was, until this
// module, a hand-recomputed number whose correctness depended on an author
// remembering to re-sum the registered guards' `timeoutMs` values and update
// a prose comment every time a guard was added, removed, or re-budgeted.
// That convention failed twice on the Stop entry alone (mt#3536, mt#3593
// each added guard budget without the recompute — the value sat stale at 21
// against a 25s sum until mt#3653 found it by hand) and once on
// UserPromptSubmit (mem#746: the comment's own prose disagreed with its own
// arithmetic). PR #2611 R1 recommended encoding the sum as DATA instead of
// prose; this module is that data.
//
// `registry.test.ts`'s "registry <-> .claude/settings.json parity" block
// consumes `deriveDispatchTimeoutMs` to assert every dispatcher entry's
// declared timeout equals the derived value for the guards actually routed
// to it — see that file for the equality check and its negative control.

/**
 * Fixed per-dispatcher-invocation margin (ms), added on top of the summed
 * guard budgets. Covers process spawn + the first guard's dynamic-import
 * cold path — overhead that exists once per dispatcher invocation,
 * independent of how many guards are registered on that event. Not derived
 * from a measurement (no per-spawn cold-boot number has been taken for the
 * dispatcher itself, unlike the DB-connect costs measured elsewhere in this
 * tree); chosen as a small, round, conservative constant. Widen this ONE
 * constant, not each entry's derived value individually, if a future
 * measurement shows it insufficient.
 */
export const DISPATCH_TIMEOUT_MARGIN_MS = 5000;

/**
 * Derive one dispatcher entry's timeout (ms) from the `timeoutMs` values of
 * the guards routed to it: SUM + `DISPATCH_TIMEOUT_MARGIN_MS`. The dispatcher
 * runs its matched guards SERIALLY (per-event, per `.claude/settings.json`'s
 * own "host-cap budget model" comments), so the host-level timeout must
 * cover the worst-case SUM, not any single guard's budget — a killed
 * dispatcher loses every remaining guard's verdict silently, which is the
 * exact failure class this derivation exists to prevent.
 */
export function deriveDispatchTimeoutMs(guardTimeoutsMs: readonly number[]): number {
  const sum = guardTimeoutsMs.reduce((total, ms) => total + ms, 0);
  return sum + DISPATCH_TIMEOUT_MARGIN_MS;
}
